const dhikrs=[['سُبْحَانَ اللَّهِ','Subhanallah'],['الْحَمْدُ لِلَّهِ','Əlhəmdulillah'],['اللَّهُ أَكْبَرُ','Allahu əkbər'],['لَا إِلَهَ إِلَّا اللَّهُ','Lə ilahə illəllah'],['اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِ مُحَمَّدٍ','Salavat']];
let resetArmed=false,quranQuery='',quranPage=0;
function tasbihState(){const s=read('basira-tasbih',{dhikr:0,target:33,counts:[0,0,0,0,0],days:{},vibrate:false});s.dhikr=Math.max(0,Math.min(4,Number(s.dhikr)||0));s.target=[33,99,100,1000].includes(Number(s.target))?Number(s.target):33;s.counts=dhikrs.map((_,i)=>Math.max(0,Math.floor(Number(s.counts?.[i])||0)));s.days=s.days||{};return s}
function tasbihPage(){const s=tasbihState(),n=s.counts[s.dhikr],within=n%s.target,pct=n&&within===0?100:within/s.target*100;return head('Təsbeh','Qəlbiniz zikrlə rahatlıq tapsın')+`<section class="tasbih-view"><div class="tasbih-options"><select aria-label="Zikr seçimi" onchange="setTasbih('dhikr',this.value)">${dhikrs.map((d,i)=>`<option value="${i}" ${s.dhikr===i?'selected':''}>${d[1]}</option>`).join('')}</select><select aria-label="Hədəf" onchange="setTasbih('target',this.value)">${[33,99,100,1000].map(t=>`<option value="${t}" ${s.target===t?'selected':''}>Hədəf: ${t}</option>`).join('')}</select></div><div class="tasbih-arabic" lang="ar" dir="rtl">${dhikrs[s.dhikr][0]}</div><button class="tasbih-counter" style="--count-progress:${pct}%" onclick="countTasbih(1)" aria-label="${dhikrs[s.dhikr][1]} zikrini bir artır"><span class="counter-core"><strong id="countValue" aria-live="polite">${n}</strong><span>${n>0&&within===0?'Hədəf tamamlandı ✓':`${within} / ${s.target}`}</span><small>Artırmaq üçün toxunun</small></span></button><div class="tasbih-meta"><span>Bu gün <b>${s.days[key(new Date())]||0}</b></span><span>Dövr <b>${Math.floor(n/s.target)}</b></span></div><div class="tasbih-actions"><button class="secondarybtn" onclick="countTasbih(-1)" ${!n?'disabled':''} aria-label="Son sayımı geri al">↶ Geri al</button><button class="secondarybtn" onclick="resetTasbih()">${resetArmed?'Bəli, sıfırla':'Sıfırla'}</button></div><label class="vibrate-option"><span>Titrəyiş <small>Cihaz dəstəklədikdə</small></span><input class="switch" aria-label="Titrəyiş" type="checkbox" ${s.vibrate?'checked':''} onchange="setTasbih('vibrate',this.checked)"></label><p class="notice center">Hər zikrin sayğacı ayrıca saxlanılır.</p></section>`}
function setTasbih(k,v){const s=tasbihState();s[k]=k==='vibrate'?!!v:Number(v);resetArmed=false;save('basira-tasbih',s);render()}
function countTasbih(delta){const s=tasbihState(),old=s.counts[s.dhikr],n=Math.max(0,old+delta),k=key(new Date());s.counts[s.dhikr]=n;s.days[k]=Math.max(0,(s.days[k]||0)+(n-old));resetArmed=false;save('basira-tasbih',s);if(delta>0&&s.vibrate&&navigator.vibrate){try{navigator.vibrate(n%s.target===0?[60,50,60]:15)}catch{}}render()}
function resetTasbih(){if(!resetArmed){resetArmed=true;render();return}const s=tasbihState();s.counts[s.dhikr]=0;save('basira-tasbih',s);resetArmed=false;render();toast('Seçilmiş zikrin sayğacı sıfırlandı.')}
function compactHome(){const n=next();return `<div class="home-heading"><div><h1 class="${personalProfile().name?'personal-greeting':''}" data-localized="true">${personalProfile().name?esc(ex('greeting',{name:personalProfile().name})):tr('Bu gün')}</h1><span>${date(placeToday())}</span>${personalProfile().purpose?`<span class="intention-line" data-localized="true">${esc(ex(personalProfile().purpose))}</span>`:''}</div><span class="badge">${esc(placeLabel())}</span></div><section class="home-next"><div><small>Növbəti namaz</small><h2>${n?names[n.i]:'Namaz vaxtları'}</h2><span>${n?n.left:timeError?'Bağlantını yoxlayın':'Yüklənir…'}</span></div><strong>${n?prayers[n.i]:'—:—'}</strong></section>${proHomeCard()}<div class="prayerstrip">${names.map((t,i)=>`<button class="prayerbox ${n?.i===i?'current':''}" onclick="go('prayers')"><span class="sun">${icons[i]}</span>${t}<strong>${prayers?.[i]||'—:—'}</strong></button>`).join('')}</div><div class="home-tools">${[['learn','♧','Namazı öyrən'],['tasbih','◉','Təsbeh'],['quran','▥','Qurani-Kərim'],['duas','♧','Gündəlik dualar'],['qibla','◈','Qiblə'],['tracker','✓','Namaz izləyicisi']].map(([r,i,t])=>`<button class="tool-tile" onclick="go('${r}')"><span>${i}</span><strong>${t}</strong></button>`).join('')}</div>${dailyDuaBanner(true)}${timeError?'<button class="textbtn" onclick="loadTimes()">Vaxtları yenidən yüklə ↻</button>':''}`}
function quranPageSize(){const h=document.querySelector("#app")?.clientHeight||((window.innerHeight||740)-121);return Math.max(1,Math.floor((h-151)/55))}
function compactQuran(){const q=quranQuery.toLocaleLowerCase('az'),list=surahs.filter(s=>(s.englishName+s.name+s.number+(s.number===1?'Fatihə':'')).toLocaleLowerCase('az').includes(q)),size=quranPageSize(),pages=Math.max(1,Math.ceil(list.length/size));quranPage=Math.min(quranPage,pages-1);return head('Qurani-Kərim','Oxu, dinlə, qəlbinə nur qat')+`<div class="toolbar"><input type="search" value="${esc(quranQuery)}" aria-label="Surə axtarışı" placeholder="Surə axtarın…" oninput="searchQuran(this.value)"></div><section class="card listgrid compact-surahs" id="surahList">${surahRows(list.slice(quranPage*size,(quranPage+1)*size))}</section><div class="quran-pagination"><button class="secondarybtn" aria-label="Əvvəlki səhifə" onclick="quranPage--;render()" ${quranPage===0?'disabled':''}>←</button><span>${quranPage+1} / ${pages} <small>· ${list.length} surə</small></span><button class="secondarybtn" aria-label="Növbəti səhifə" onclick="quranPage++;render()" ${quranPage>=pages-1?'disabled':''}>→</button></div>`}
function searchQuran(q){quranQuery=q;quranPage=0;const input=document.querySelector('input[type=search]'),pos=input?.selectionStart;render();const nextInput=document.querySelector('input[type=search]');nextInput?.focus?.();try{nextInput?.setSelectionRange?.(pos,pos)}catch{}}
